 "content": "from collections import Counter


def transform(grid):
    """Restore dense, mostly rectangular colored objects and discard speckle noise."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Enumerate rectangles whose dominant color is sufficiently dense to be an
    # object; isolated and scattered pixels cannot meet the support threshold.
    candidates = []
    colors = set(v for row in grid for v in row if v != background)
    for color in colors:
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if area < 6:
                            continue
                        hits = sum(grid[r][c] == color
                                   for r in range(r0, r1 + 1)
                                   for c in range(c0, c1 + 1))
                        if hits >= 4 and hits / area >= 0.65:
                            candidates.append((area, hits / area, hits,
                                               color, r0, r1, c0, c1))

    candidates.sort(reverse=True)
    objects = []
    for area, density, hits, color, r0, r1, c0, c1 in candidates:
        # Keep the largest qualifying rectangle for an object, rather than its
        # many nested subrectangles.
        duplicate = False
        for old_color, a0, a1, b0, b1 in objects:
            overlap = max(0, min(r1, a1) - max(r0, a0) + 1) * max(
                0, min(c1, b1) - max(c0, b0) + 1)
            if old_color == color and overlap >= 0.5 * min(
                    area, (a1 - a0 + 1) * (b1 - b0 + 1)):
                duplicate = True
                break
        if not duplicate:
            objects.append((color, r0, r1, c0, c1))

    out = [[background for _ in range(w)] for _ in range(h)]
    for color, r0, r1, c0, c1 in objects:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
