 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != background}
    objects = []

    # Dense rectangular patches are the objects; scattered off-color pixels are
    # corruption. A prefix sum makes it cheap to score every possible rectangle.
    for color in colors:
        ps = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                ps[r + 1][c + 1] = (ps[r][c + 1] + ps[r + 1][c]
                                      - ps[r][c] + (grid[r][c] == color))

        def total(r0, r1, c0, c1):
            return (ps[r1 + 1][c1 + 1] - ps[r0][c1 + 1]
                    - ps[r1 + 1][c0] + ps[r0][c0])

        candidates = []
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                rh = r1 - r0 + 1
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        area = rh * (c1 - c0 + 1)
                        if area < 6:
                            continue
                        hits = total(r0, r1, c0, c1)
                        density = hits / area
                        # Small objects can have a greater fraction of their
                        # cells corrupted; larger blocks are required to be dense.
                        if (area <= 8 and density >= 0.60) or (area > 8 and density >= 0.78):
                            candidates.append((area, density, hits, r0, r1, c0, c1))

        candidates.sort(reverse=True)
        chosen = []
        for area, density, hits, r0, r1, c0, c1 in candidates:
            duplicate = False
            for old_area, a0, a1, b0, b1 in chosen:
                overlap = max(0, min(r1, a1) - max(r0, a0) + 1) * max(
                    0, min(c1, b1) - max(c0, b0) + 1)
                if overlap >= 0.5 * min(area, old_area):
                    duplicate = True
                    break
            if not duplicate:
                chosen.append((area, r0, r1, c0, c1))
                objects.append((color, r0, r1, c0, c1))

    out = [[background] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in objects:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
